 static final Map<Object,Track> TRACKS=new WeakHashMap<>();static final class Track{long start,end;double rise;First24.Frame[] initial=new First24.Frame[2];Track(Object p,double y){for(int side=0;side<2;side++)initial[side]=running(p,side);start=BoxingClient16.CLOCK.getAsLong();rise=Math.max(.3,Math.min(2,y-R.coord(p,"Y")));}}
 static void start(Object p,double y){TRACKS.put(p,new Track(p,y));}static void stop(Object p){Track t=TRACKS.get(p);if(t!=null)t.end=BoxingClient16.CLOCK.getAsLong();}
 static double phase(Object p){Track t=TRACKS.get(p);if(t==null)return -1;long now=BoxingClient16.CLOCK.getAsLong();double phase=t.end!=0?.87+(now-t.end)/200_000_000d*.13:Math.min(.87,(now-t.start)/(650_000_000d+t.rise*100_000_000d));if(t.end==0&&!Parkour20.active(p)&&now-t.start>1_600_000_000L){t.end=now;phase=.87;}if(phase>=1){TRACKS.remove(p);return -1;}return phase;}
