 static First24.Frame first(Object p,int side){double phase=phase(p);if(phase<0)return null;Track t=TRACKS.get(p);var f=blend(t.initial[side],frame(side,phase,t.rise),Motion20.smooth(phase/.15));return blend(f,running(p,side),Motion20.smooth((phase-.86)/.14));}
